cd "$(dirname "$0")"
fail=0
for s in check_shadows.py check_tropical.py check_cohomology.py check_hallucination.py check_barr.py check_twocat.py check_infogeom.py check_places.py companion/check_agents.py engine/check_pce.py engine/check_icl.py engine/check_integrate.py engine/check_complex.py engine/check_cohomology_engine.py engine/check_lift.py engine/check_gs.py engine/check_places_engine.py engine/check_overlap.py engine/check_overlap2.py engine/check_cover.py engine/check_perturb.py engine/check_strata.py engine/check_bridge.py engine/check_cbd.py engine/check_toric.py engine/check_updates.py engine/check_persist.py engine/check_persist2.py engine/check_level2.py engine/check_scheme.py engine/check_ladder.py engine/check_noncomm.py engine/check_masked.py engine/check_masked_gauge.py engine/check_qglue.py engine/check_npa.py engine/check_fingerprint.py engine/check_cbdfrac.py engine/check_ball.py engine/check_coxeter.py engine/check_cup.py engine/check_birth.py engine/check_invariant.py engine/check_timesheaf.py engine/check_decision_segment.py engine/check_injection.py engine/check_sources.py engine/check_lifting.py engine/check_capstone.py engine/check_descent.py engine/check_csd.py engine/check_quantum.py engine/check_markov.py engine/check_roumen.py engine/check_tangent.py engine/check_tangent_decide.py engine/check_layers.py engine/check_restriction.py engine/check_covers.py engine/check_syzygy.py engine/check_higher.py engine/check_signs.py engine/check_cover_strata.py engine/check_ehrhart.py engine/check_levels.py engine/check_three.py engine/check_frames.py engine/check_ident.py engine/check_betti_large.py engine/check_relevance.py engine/check_order3.py engine/check_inversion.py engine/check_context.py engine/check_tangent_layers.py engine/check_jumps.py engine/check_orders.py engine/check_fans.py engine/check_para.py engine/check_statfan.py engine/check_graded.py engine/check_degen.py engine/check_degen_d.py engine/check_toricreal.py engine/check_effects.py engine/check_environment.py engine/check_envhier.py engine/check_kahlerbridge.py engine/check_datawalls.py engine/check_contingency_toric.py engine/check_couplingfibre.py engine/check_leximin.py engine/check_floermorph.py engine/check_colbind.py engine/check_cpl24.py engine/check_chambers24_cert.py engine/check_pentpath.py engine/check_selcomp.py engine/check_selbin.py engine/check_selcert.py engine/check_selfloer.py engine/check_selnat.py engine/check_margsec.py engine/check_poisonflip.py engine/check_poisongeom.py engine/check_invsec.py engine/check_voigeom.py engine/check_voidet.py engine/check_algsel.py engine/check_viability.py engine/check_holonomy.py engine/check_fishervoi.py engine/check_blochtoric.py engine/check_signtwist.py engine/check_pseudoknot.py engine/check_pdknot.py engine/check_cutglue.py engine/check_boundary.py engine/check_chainglue.py engine/check_tlmemo.py engine/check_elimquot.py engine/check_tamper.py engine/check_miscal.py engine/check_watch.py engine/check_braidknot.py engine/check_tiebraid.py engine/check_ordrev.py engine/check_revtraj.py engine/check_dmmemory.py engine/check_dmledger.py engine/check_poolcond.py engine/check_raagbraid.py engine/check_bklband.py engine/check_stranddefect.py engine/check_credalbraid.py engine/check_masking.py engine/check_imprecctx.py engine/check_braidvalue.py engine/check_credalfield.py engine/check_fieldholonomy.py engine/check_kerneltransport.py engine/check_refitdefect.py engine/check_historytrace.py engine/check_refitcommute.py engine/check_selectorlink.py engine/check_study26.py engine/check_brokerage.py engine/check_pseudoprob.py engine/check_ledger.py engine/check_fracture.py engine/check_fracband.py engine/check_blueprint.py engine/check_conewise.py engine/check_fracstrata.py engine/worked_example.py engine/worked_example4.py engine/worked_descent.py check_grid.py check_bc_test.py; do
  echo "== $s"; t0=$SECONDS
  out=$(python3 "$s" 2>&1); echo "$out" | grep -E "^(PASS|FAIL)" | sed 's/   \[.*//'
  echo "$out" | grep -q "^FAIL" && fail=1
  echo "$out" | tail -1; echo "   ($((SECONDS - t0)) s)"
done
[ $fail -eq 0 ] && echo "ALL CHECKS PASSED" || { echo "SOME CHECKS FAILED"; exit 1; }
